ROOT=Path(__file__).resolve().parents[3];PACKET=ROOT/'research/voevodsky/total_energy_parameter_match_lands_on_a_triple_relative_divisor.md';PARAM=ROOT/'research/voevodsky/common_kummer_parameter_exists_on_total_energy_specialization.md';RESULT=ROOT/'research/voevodsky/results/total_energy_triple_relative_divisor.json';mB,mC,mE,lam=s.symbols('mB mC mE lam');RB=s.Matrix([[1,0,0],[0,0,0],[1,0,0]]);RC=s.Matrix([[0,1,1],[0,0,0],[0,1,1]]);RE=s.Matrix([[1,-1,-1],[-1,1,1],[0,0,0]]);R=s.expand(mB)*RB+s.expand(mC)*RC+s.expand(mE)*RE;Req=R.subs({mB:1,mC:1,mE:1});cp=s.factor(R.charpoly(lam).as_expr());checks={'parameter_source_has_X1_equals_Y':'X_{1,\\rm rel}=Y_{\\rm rel}' in PARAM.read_text(encoding='utf-8'),'parameter_source_has_X2_equals_minusY':'X_{2,\\rm rel}=-Y_{\\rm rel}' in PARAM.read_text(encoding='utf-8'),'triple_vanishing':s.simplify(s.Symbol('Y')-s.Symbol('Y'))==0 and s.simplify(-s.Symbol('Y')+s.Symbol('Y'))==0 and s.simplify(s.Symbol('Y')-s.Symbol('Y'))==0,'characteristic_polynomial':s.expand(cp-lam*(lam-2*mE)*(lam-mB-mC))==0,'generic_normal_kernel_one':R.rank()==2,'equal_residue_exact':Req==s.Matrix([[2,0,0],[-1,1,1],[1,1,1]]),'equal_residue_rank_two':Req.rank()==2,'equal_residue_eigenvalues':Req.eigenvals()=={s.Integer(2):2,s.Integer(0):1},'ordinary_pullback_rejected':'cannot by itself define the desired connection comparison' in PACKET.read_text(encoding='utf-8'),'nearby_cycle_gate':'normal-deformation and nearby-cycle map' in PACKET.read_text(encoding='utf-8')};checks={k:bool(v) for k,v in checks.items()};result={'schema':'marici.voevodsky.total-energy-triple-relative-divisor.v1','packet_sha256':sha256(PACKET.read_bytes()).hexdigest(),'parameter_packet_sha256':sha256(PARAM.read_bytes()).hexdigest(),'vanishing_factors':['X1-Y','X2+Y','X1+X2'],'normal_residue':[[str(x) for x in R.row(i)] for i in range(3)],'characteristic_polynomial':str(cp),'equal_order_residue':[[int(x) for x in Req.row(i)] for i in range(3)],'checks':checks,'passed':all(checks.values()),'disposition':{'ordinary_connection_pullback':'undefined','normal_residue_flat_line':'present','vanishing_orders':'not source-authorized','nearby_cycle_map':'missing'}};RESULT.write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({'passed':result['passed'],'checks':checks,'disposition':result['disposition']}));raise SystemExit(0 if result['passed'] else 1)
